import { app, BrowserWindow, Menu, ipcMain, screen, session } from 'electron';
import fs from 'fs';
import path from 'path';
import { registerSecureTokenStore } from './secureTokenStore';
declare const process: NodeJS.Process;
// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require('electron-squirrel-startup')) {
  app.quit();
}

// Matches Squirrel's shortcut ID so the taskbar groups and pins Projello correctly
app.setAppUserModelId('com.squirrel.Projello.Projello');

// Only one Projello at a time: opening it again focuses the existing window
if (!app.requestSingleInstanceLock()) {
  app.quit();
}
app.on('second-instance', () => {
  const win = BrowserWindow.getAllWindows()[0];
  if (!win) return;
  if (win.isMinimized()) win.restore();
  win.focus();
});

// The app used to be called "frontend". Bring over its saved sign-in and settings once,
// so renaming it to Projello doesn't sign everyone out or reset their theme.
// Runs before Chromium starts: "Local State" holds the key that decrypts session.bin,
// so it has to be in place before Chromium creates a fresh one.
const migrateOldUserData = (): void => {
  const oldDir = path.join(app.getPath('appData'), 'frontend');
  const newDir = app.getPath('userData');
  if (oldDir === newDir || !fs.existsSync(oldDir) || fs.existsSync(path.join(newDir, 'Local State'))) return;
  try {
    fs.mkdirSync(newDir, { recursive: true });
    for (const item of ['Local State', 'Local Storage', 'session.bin', 'window-state.json']) {
      const from = path.join(oldDir, item);
      if (fs.existsSync(from)) fs.cpSync(from, path.join(newDir, item), { recursive: true });
    }
  } catch {
    // Not worth blocking start-up: the worst case is signing in again
  }
};

// Brand colours for the window frame and the title bar buttons
const THEME = {
  light: { background: '#F4F2EB', symbols: '#28332b' },
  dark: { background: '#28332b', symbols: '#f7f7f3' },
} as const;
const TITLE_BAR_HEIGHT = 32;

// Remember where the window was, so Projello reopens the same size and place
type WindowState = { x?: number; y?: number; width: number; height: number; maximized?: boolean };
const stateFile = (): string => path.join(app.getPath('userData'), 'window-state.json');

const loadWindowState = (): WindowState => {
  const fallback: WindowState = { width: 1280, height: 820 };
  try {
    const saved = JSON.parse(fs.readFileSync(stateFile(), 'utf8')) as WindowState;
    // Ignore a saved position that is no longer on any screen (for example an unplugged monitor)
    const onScreen = screen.getAllDisplays().some(({ workArea: a }) =>
      saved.x !== undefined && saved.y !== undefined &&
      saved.x >= a.x - 50 && saved.y >= a.y - 50 && saved.x < a.x + a.width && saved.y < a.y + a.height);
    return onScreen ? saved : { ...fallback, maximized: saved.maximized };
  } catch {
    return fallback;
  }
};

const saveWindowState = (win: BrowserWindow): void => {
  try {
    const bounds = win.getNormalBounds();
    fs.writeFileSync(stateFile(), JSON.stringify({ ...bounds, maximized: win.isMaximized() }));
  } catch {
    // Not critical
  }
};

const createWindow = (): void => {
  const state = loadWindowState();

  // Create the browser window.
  const mainWindow = new BrowserWindow({
    title: 'Projello',
    x: state.x,
    y: state.y,
    width: state.width,
    height: state.height,
    minWidth: 1024,
    minHeight: 680,
    center: state.x === undefined,
    // Paint the brand colour straight away and show only once the app has drawn,
    // so there is no white flash on launch
    show: false,
    backgroundColor: THEME.dark.background,
    // Projello's own colours in the title bar instead of the default Windows frame
    titleBarStyle: 'hidden',
    titleBarOverlay: {
      color: THEME.light.background,
      symbolColor: THEME.light.symbols,
      height: TITLE_BAR_HEIGHT,
    },
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      // Stated explicitly so a future Electron default change can't loosen them
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
    },
  });

  mainWindow.once('ready-to-show', () => {
    if (state.maximized) mainWindow.maximize();
    mainWindow.show();
  });
  mainWindow.on('close', () => saveWindowState(mainWindow));

  // Apply a stricter, environment-aware CSP (allows local API + dev tooling when not packaged)
  const isDev = !app.isPackaged;

const connectSrc = [
  "'self'",
  'https://projello-api.onrender.com',
  'wss://projello-api.onrender.com',
  ...(isDev ? ['http://localhost:*', 'ws://localhost:*', 'ws://127.0.0.1:*'] : []),
];//test

  const cspDirectives = [
    "default-src 'self'",
    "base-uri 'self'",
    "object-src 'none'",
    "frame-ancestors 'none'",
    "script-src 'self' 'unsafe-inline' 'unsafe-eval'", // keep for Electron/Webpack dev compatibility
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: https:",
    "font-src 'self' data:",
    `connect-src ${connectSrc.join(' ')}`,
  ];

  session.defaultSession.webRequest.onHeadersReceived((details, callback) => {
    const responseHeaders = { ...details.responseHeaders };
    responseHeaders['Content-Security-Policy'] = [cspDirectives.join('; ')];

    callback({ responseHeaders });
  });

  // and load the index.html of the app.
  mainWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY);

  // DevTools only while developing, never in the packaged app
  if (isDev) {
    mainWindow.webContents.openDevTools();
  }
};

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
migrateOldUserData();

app.on('ready', () => {
  // No File/Edit/View menu bar: Projello has its own navigation
  Menu.setApplicationMenu(null);
  registerSecureTokenStore();

  // The renderer reports the current theme so the title bar buttons match it
  ipcMain.on('theme:changed', (event, theme: unknown) => {
    const colours = theme === 'dark' ? THEME.dark : THEME.light;
    const win = BrowserWindow.fromWebContents(event.sender);
    win?.setTitleBarOverlay({ color: colours.background, symbolColor: colours.symbols, height: TITLE_BAR_HEIGHT });
    win?.setBackgroundColor(colours.background);
  });

  createWindow();
});

// Quit when all windows are closed, except on macOS. There, it's common
// for applications and their menu bar to stay active until the user quits
// explicitly with Cmd + Q.
app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('activate', () => {
  // On OS X it's common to re-create a window in the app when the
  // dock icon is clicked and there are no other windows open.
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});

